+                        target_commit
+                            .committer()
+                            .map_err(|e| VcsError::Git(format!("could not read target committer: {e}")))?
+                    }
+                };
                 self.repo
                     .tag(
                         name,
                         oid,
                         gix::object::Kind::Commit,
-                        None,
